declare s clob;n number;
 procedure same(p_name varchar2,p_type varchar2,p_hash varchar2,p_code varchar2)is begin
  dbms_lob.createtemporary(s,true);
  for r in(select TEXT from USER_SOURCE where NAME=p_name and TYPE=p_type order by LINE)loop dbms_lob.append(s,replace(r.TEXT,chr(13),''));end loop;
  if dbms_lob.getlength(s)=0 or rawtohex(sys.dbms_crypto.hash(rtrim(s,chr(10)),sys.dbms_crypto.hash_sh256))<>p_hash then raise_application_error(-20999,p_code||':'||p_name||':'||p_type);end if;
  dbms_lob.freetemporary(s);
 end;
begin
 same('RRL_STOCK_UNIT_CORE','PACKAGE','98087FB04676531BB24BB84557244168315BF23638B7FB5C671AEA7A47FE4E03','AFTER_SOURCE_MISMATCH');
 same('RRL_STOCK_UNIT_CORE','PACKAGE BODY','DD03550CF5A185F4A513E233D1FA2BE55EB7764435129EB6FB62CEB8E3434E65','AFTER_SOURCE_MISMATCH');
 same('RRL_STOCK_INVENTORY_CMD','PACKAGE BODY','F491ED14050AAEAFC33A010223CCA9ADE49A6CD78C72260513A9CC5675FBBD07','AFTER_SOURCE_MISMATCH');
 same('RRL_STOCK_INVENTORY_CMD','PACKAGE','07A6AB9A5CB264CE9715801706D0BCD7CF05948D3A3BB39D84E6761208E4826E','DEPENDENCY_CHANGED');
 same('RRL_STOCK_CTX_API','PACKAGE','D31EE0E0A41E64B04C3E15E24C452A130CB1930DF78C3E72A1F3F656E1EDD586','DEPENDENCY_CHANGED');
 same('RRL_STOCK_PLAN_HELPER','PACKAGE','D23535D9AB6E1B735147CA77C4D31AD1727DC1F53B8C0CB89FD53515AE5444CE','DEPENDENCY_CHANGED');
 same('RRL_STOCK_BALANCE_CORE','PACKAGE','8D326FD36F95B2672F804FAB0EF7B0B431DA66630703049FA5BD5AA9E6973004','DEPENDENCY_CHANGED');
 same('RRL_STOCK_LOCK_API','PACKAGE','5E65D9B3D4B3FB367EE698B72709BF4FD396EDF2177156D73A7EB7ECF787ACD4','DEPENDENCY_CHANGED');
 same('RRL_TRADE_STOCK_GUARD','PACKAGE','555A92C50609C9198308AE1E4129AECCB34E891ADC14170F016B739596B447AA','DEPENDENCY_CHANGED');
 select count(*)into n from USER_OBJECTS where OBJECT_NAME in('RRL_INVENTORY_LOSS_UNIT','RRL_INVENTORY_FOUND_UNIT','RRL_INV_LOSS_UNIT_LOT_IX','RRL_INV_LOSS_UNIT_APPEND','RRL_INV_FOUND_UNIT_APPEND');if n<>5 then raise_application_error(-20999,'INVENTORY_FOUND_OBJECT_MISSING');end if;
 select count(*)into n from USER_OBJECTS where STATUS='INVALID';if n<>0 then raise_application_error(-20999,'INVALID_OBJECTS');end if;
 select count(*)into n from USER_ERRORS where NAME in('RRL_STOCK_UNIT_CORE','RRL_STOCK_INVENTORY_CMD');if n<>0 then raise_application_error(-20999,'COMPILE_ERRORS');end if;
end;
